import { applyOverrides, loadOverrides, type Overrides } from './overrides';
import { parseMuseumConfig } from './schema';

export async function loadMuseumConfig(
  fetcher: typeof fetch = fetch,
  baseUrl = import.meta.env.BASE_URL,
  overrides: Overrides = loadOverrides(),
) {
  const base = baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`;
  const response = await fetcher(`${base}config/museum.json`, { cache: 'no-cache' });
  if (!response.ok) throw new Error(`配置加载失败：HTTP ${response.status}`);
  const parsed = parseMuseumConfig(await response.json());
  // 页面内「地图设置」选定的默认视图/位置覆盖在配置文件之上，刷新后依然生效。
  return { ...parsed, config: applyOverrides(parsed.config, overrides) };
}

export function resolveAssetUrl(path: string, baseUrl = import.meta.env.BASE_URL) {
  if (path.startsWith('https://')) return path;
  const base = baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`;
  return `${base}${path.replace(/^\/+/, '')}`;
}
