/**
 * 低优先级预取（仅在用户悬停/聚焦入口时触发一次）。
 *
 * 目的：把最重的懒加载链路提前到“用户即将进入”的阶段开始下载，
 * 减少真正点击后的等待：
 * - 设备模型入口 → DevicePage（连带 three-engine 渲染链路）
 * - 数字档案入口 → ArchivePage
 * - PDF/模型档案卡 → PdfViewer（连带 pdf-engine）/ ModelResourceViewer
 *
 * 动态 import 已被模块缓存，重复调用不会重复下载。
 */
export function prefetchRouteModule(route: string) {
  if (route.startsWith('/devices')) void import('../features/devices/DevicePage');
  else if (route.startsWith('/archive')) void import('../features/archive/ArchivePage');
  else if (route.startsWith('/panorama')) void import('../features/panorama/PanoramaPage');
  else if (route.startsWith('/map')) void import('../features/map/MapPage');
}

export function prefetchResourceViewer(kind: string) {
  if (kind === 'pdf') void import('../features/archive/PdfViewer');
  else if (kind === 'model') void import('../features/devices/ModelResourceViewer');
}
