/**
 * Web Mercator（EPSG:3857）基础换算。
 * 放在 shared 里是因为配置层（把经纬度点位换算成归一化坐标）与地图渲染层都要用。
 */

export interface GeoBounds {
  west: number;
  south: number;
  east: number;
  north: number;
}

export const MAX_MERCATOR_LAT = 85.05112878;

export function lngToMercator(lng: number): number {
  return (lng + 180) / 360;
}

export function latToMercator(lat: number): number {
  const clamped = Math.max(-MAX_MERCATOR_LAT, Math.min(MAX_MERCATOR_LAT, lat));
  const sin = Math.sin((clamped * Math.PI) / 180);
  return 0.5 - Math.log((1 + sin) / (1 - sin)) / (4 * Math.PI);
}

/** 经纬度范围的墨卡托宽高比。 */
export function mercatorAspect(bounds: GeoBounds): number {
  const width = lngToMercator(bounds.east) - lngToMercator(bounds.west);
  const height = latToMercator(bounds.south) - latToMercator(bounds.north);
  return height > 0 ? width / height : 1;
}

/**
 * 把经纬度换算成相对某范围的归一化坐标（0~1，左上为原点）。
 * 地图点位的 `x/y` 就是这个坐标系；配置里也可以直接写 `lng/lat`，由配置层用这个函数换算。
 */
export function normalizeLngLat(lng: number, lat: number, bounds: GeoBounds): { x: number; y: number } {
  const spanX = lngToMercator(bounds.east) - lngToMercator(bounds.west);
  const spanY = latToMercator(bounds.south) - latToMercator(bounds.north);
  if (spanX <= 0 || spanY <= 0) return { x: 0.5, y: 0.5 };
  return {
    x: (lngToMercator(lng) - lngToMercator(bounds.west)) / spanX,
    y: (latToMercator(lat) - latToMercator(bounds.north)) / spanY,
  };
}

/** 某一层级的瓦片编号换算成经纬度范围（XYZ 方案，左上为原点）。 */
export function tileBounds(zoom: number, minX: number, maxX: number, minY: number, maxY: number): GeoBounds {
  const count = 2 ** zoom;
  return {
    west: mercatorToLng(minX / count),
    east: mercatorToLng((maxX + 1) / count),
    north: mercatorToLat(minY / count),
    south: mercatorToLat((maxY + 1) / count),
  };
}

export function mercatorToLng(value: number): number {
  return value * 360 - 180;
}

export function mercatorToLat(value: number): number {
  return (180 / Math.PI) * Math.atan(Math.sinh(Math.PI * (1 - 2 * value)));
}

/**
 * `normalizeLngLat` 的逆运算：把底图上的归一化坐标换算回经纬度。
 * 页面内「点选位置」用它把点击位置变成可写进配置的经纬度。
 */
export function lngLatFromNormalized(x: number, y: number, bounds: GeoBounds): { lng: number; lat: number } {
  const spanX = lngToMercator(bounds.east) - lngToMercator(bounds.west);
  const spanY = latToMercator(bounds.south) - latToMercator(bounds.north);
  if (spanX <= 0 || spanY <= 0) return { lng: bounds.west, lat: bounds.north };
  return {
    lng: mercatorToLng(lngToMercator(bounds.west) + spanX * x),
    lat: mercatorToLat(latToMercator(bounds.north) + spanY * y),
  };
}
