import { useEffect, useState } from 'react';
import { useFpsCounter } from './useFpsCounter';

interface ResourceStat {
  bytes: number;
  count: number;
  slowest: { name: string; ms: number; bytes: number } | null;
}

function useResourceStats() {
  const [stats, setStats] = useState<ResourceStat>({ bytes: 0, count: 0, slowest: null });

  useEffect(() => {
    const resources = performance.getEntriesByType('resource') as PerformanceResourceTiming[];
    const snapshot = (list?: PerformanceResourceTiming[]) => {
      const all = list ? [...resources, ...list] : [...resources];
      let bytes = 0;
      let count = 0;
      let slowest: ResourceStat['slowest'] = null;
      for (const entry of all) {
        const size = entry.transferSize || entry.encodedBodySize || 0;
        if (size > 0) {
          bytes += size;
          count += 1;
        }
        const duration = entry.responseEnd - entry.fetchStart;
        if (duration > 0 && (!slowest || duration > slowest.ms)) {
          const name = entry.name.split('/').pop() ?? entry.name;
          slowest = { name, ms: Math.round(duration), bytes: size };
        }
      }
      setStats({ bytes, count, slowest });
    };
    const observer = new PerformanceObserver(list => snapshot(list.getEntries() as PerformanceResourceTiming[]));
    observer.observe({ type: 'resource', buffered: true });
    snapshot();
    return () => observer.disconnect();
  }, []);

  return stats;
}

/**
 * Debug HUD shown when the page is opened with `?perf=1`. Reports live frame
 * rate, frame time, input latency, cumulative network transfer and the slowest
 * single resource load for real-device acceptance.
 */
export function PerformanceOverlay() {
  const { fps, frameTime, inputLatency } = useFpsCounter();
  const { bytes, slowest } = useResourceStats();
  const frameTimeClass = frameTime > 33 ? 'is-slow' : frameTime > 20 ? 'is-warn' : undefined;

  return (
    <div className="perf-overlay" aria-hidden="true">
      <span className={frameTimeClass}>{fps} FPS</span>
      <span>{frameTime} ms</span>
      {inputLatency > 0 && <span>响应 {inputLatency} ms</span>}
      {bytes > 0 && <span>↓{(bytes / 1048576).toFixed(1)} MB</span>}
      {slowest && <span title={slowest.name}>最慢 {(slowest.ms / 1000).toFixed(1)}s</span>}
    </div>
  );
}
