import { z } from 'zod';
import { normalizeLngLat } from '../shared/geo';

const vec3Schema = z.tuple([z.number(), z.number(), z.number()]);
const assetUrlSchema = z.string().min(1).refine(value => !value.startsWith('http:'), '素材地址必须使用 HTTPS 或站内相对路径');

/**
 * 资料与站内对象的关联（**多对多**，关系住在资料这一侧）：
 * - `device` / `site`：指向 devices[].id / siteModel.id；
 * - `program`：项目、机构、行业级的资料（荣誉、名录、科普活动、宣传影像），不挂在任何一台设备上。
 *
 * 为什么关系放在资料侧：一份资料讲的是"什么事"，而不是"属于哪台设备的附件"。
 * 设备页要显示的资料由这里的 about 反查派生（见 parseMuseumConfig），
 * 因此"把项目级资料挂在设备下"这种语义错位在数据结构上就不再可能。
 */
export const resourceAboutSchema = z.discriminatedUnion('kind', [
  z.object({ kind: z.literal('device'), id: z.string().min(1) }),
  z.object({ kind: z.literal('site'), id: z.string().min(1) }),
  z.object({ kind: z.literal('program') }),
]);

/** 事件类型（受控词表写在配置里：策展口径变化只改数据，不改代码）。 */
export const eventTypeSchema = z.object({
  id: z.string().min(1),
  label: z.string().min(1),
});

/** 策展专辑：把资料按"讲哪条故事线"成组，替代把分类写死在目录或代码里。 */
export const collectionSchema = z.object({
  id: z.string().min(1),
  label: z.string().min(1),
  summary: z.string().default(''),
});

export const resourceSchema = z.object({
  id: z.string().min(1),
  title: z.string().min(1),
  /** 媒体格式，只决定用哪个查看器；它不是分类体系（分类看 eventType / about / collectionIds）。 */
  kind: z.enum(['image', 'video', 'pdf', 'model']),
  url: assetUrlSchema,
  poster: assetUrlSchema.optional(),
  /**
   * 列表用缩略图（`content/thumbs/<原名>.jpg`，540×405 的 4:3 居中裁切）。
   * 由 `npm run thumbs` 生成、随 `source/assets` 一起发布；不填则退回 `url`／`poster` 原图，
   * 再没有就显示"纸张"占位卡。**别直接把 400 KB 的原图当缩略图用**——一屏 6 张就是 2.4 MB。
   */
  thumb: assetUrlSchema.optional(),
  description: z.string().default(''),
  /**
   * 来源层（凭证，只读）：院方交付时的原始位置。
   * 原件目录**不参与**站内检索与排布，只用于追溯"这份资料是怎么来的"。
   */
  source: z.object({
    /** 相对仓库根的原始路径，例如 `六、附件图片/核心物项/1-……（拍摄于1980年）.png`。 */
    path: z.string().min(1),
    /** 申报材料章节（`六、附件图片` / `七、视频资料`），说明它是随哪一批材料交来的。 */
    dossier: z.string().default(''),
  }).optional(),
  /** 描述层：机器可读的年代，供时间轴与筛选使用。**查不到就不填**，不要用推断值冒充。 */
  period: z.object({
    year: z.number().int().optional(),
    /** 原始表述（例如 `拍摄于1980年`），保留交付口径。 */
    label: z.string().default(''),
  }).optional(),
  /** 事件类型 id，必须能在 eventTypes 里找到。 */
  eventType: z.string().min(1).optional(),
  about: z.array(resourceAboutSchema).default([]),
  /** 策展专辑 id，必须能在 collections 里找到。 */
  collectionIds: z.array(z.string().min(1)).default([]),
  /**
   * 载体形态：PDF 页数 / 视频时长（秒）。
   * 两个用途：① 卡片上显示"图纸 · 56 页""视频 · 4:07"，让用户在平铺列表里也能分辨格式与体量；
   * ② 给资料内部锚点（页码、时间码）做上限校验——越界的锚点会在构建期被挡下。
   */
  extent: z.object({
    pages: z.number().int().positive().optional(),
    seconds: z.number().int().positive().optional(),
  }).optional(),
  /** 权利信息；缺省视为"本站默认可公开展示"。分级资料在这里声明。 */
  rights: z.object({
    level: z.enum(['public', 'internal', 'licensed']).default('public'),
    credit: z.string().default(''),
    license: z.string().default(''),
  }).optional(),
});

export const devicePartSchema = z.object({
  id: z.string().min(1),
  label: z.string().min(1),
  description: z.string().default(''),
  nodeNames: z.array(z.string().min(1)).min(1),
  level: z.number().int().min(1).max(4),
  direction: vec3Schema,
  distance: z.number().nonnegative(),
  sequence: z.tuple([z.number().min(0).max(1), z.number().min(0).max(1)]),
  /** 可选子装配组：同组的部件作为一个整体拆解，再按组内顺序展开。 */
  group: z.string().min(1).optional(),
  resourceIds: z.array(z.string()).default([]),
}).refine(value => value.sequence[0] <= value.sequence[1], {
  message: '拆解序列起点不能晚于终点',
  path: ['sequence'],
});

export const modelSourceKinds = ['gltf', 'fbx', 'obj', 'stl'] as const;
export type ModelSourceKind = (typeof modelSourceKinds)[number];

/** 文件型模型来源（设备与场地共用）。 */
export const fileModelSourceSchema = z.discriminatedUnion('kind', [
  z.object({ kind: z.literal('gltf'), url: assetUrlSchema }),
  z.object({ kind: z.literal('fbx'), url: assetUrlSchema }),
  z.object({ kind: z.literal('obj'), url: assetUrlSchema }),
  z.object({ kind: z.literal('stl'), url: assetUrlSchema }),
]);

export const cameraSchema = z.object({
  position: vec3Schema,
  target: vec3Schema,
  minDistance: z.number().positive(),
  maxDistance: z.number().positive(),
}).refine(value => value.minDistance < value.maxDistance, '相机最小距离必须小于最大距离');

export const deviceSchema = z.object({
  id: z.string().min(1),
  name: z.string().min(1),
  summary: z.string(),
  poster: assetUrlSchema,
  source: z.discriminatedUnion('kind', [
    z.object({ kind: z.literal('procedural') }),
    z.object({ kind: z.literal('gltf'), url: assetUrlSchema }),
    z.object({ kind: z.literal('fbx'), url: assetUrlSchema }),
    z.object({ kind: z.literal('obj'), url: assetUrlSchema }),
    z.object({ kind: z.literal('stl'), url: assetUrlSchema }),
  ]),
  camera: cameraSchema,
  /** 可选拆解编排；缺省时按部件自身 direction/distance/sequence 播放。 */
  explosion: z.object({
    mode: z.enum(['grouped']).optional(),
    /** 外层组先拆（由外向内）还是内层先拆（由内向外）。缺省：外层组先。 */
    order: z.enum(['outside-in', 'inside-out']).default('outside-in'),
    /** 总播放时长参考（秒），用于把自动拆解/滑杆换算成一致节奏。 */
    duration: z.number().positive().default(4.5),
    /**
     * 终态排布方式。packing(缺省)：按包围盒装箱到互不相交的格子（保证终态不重叠）；
     * none：只做 A 阶段起吊，不做装箱铺开（例如已由 grouped 编排接管时）。
     */
    layout: z.enum(['packing', 'none']).default('packing'),
  }).optional(),
  parts: z.array(devicePartSchema),
  /**
   * 设备关联的资料 id。**由 resources[].about 派生**，配置里不要再手写：
   * 手写值与派生值不一致时 parseMuseumConfig 记一条 issue，并以派生值为准（单一来源）。
   */
  resourceIds: z.array(z.string()).default([]),
});

export const panoramaSchema = z.object({
  id: z.string().min(1),
  name: z.string().min(1),
  description: z.string().default(''),
  /** 站内（或远程 HTTPS）等距柱状全景图；与 embedUrl 二选一。 */
  image: assetUrlSchema.optional(),
  /**
   * 外部全景作品的嵌入地址（例如 720yun 的作品页 `https://www.720yun.com/vr/<id>`）。
   * 用 iframe 直接呈现第三方播放器：内容由对方维护、**运行期必须联网**，
   * 且嵌入模式下对方通常不提供全屏/VR/陀螺仪。与 image 二选一。
   */
  embedUrl: assetUrlSchema.optional(),
  initialYaw: z.number().default(0),
  initialPitch: z.number().min(-90).max(90).default(0),
  hotspots: z.array(z.object({
    id: z.string().min(1),
    label: z.string().min(1),
    targetId: z.string().min(1),
    yaw: z.number(),
    pitch: z.number().min(-90).max(90),
  })).default([]),
}).refine(value => Boolean(value.image) !== Boolean(value.embedUrl), {
  message: '全景必须且只能提供 image 或 embedUrl 之一',
  path: ['image'],
});

/** 站内全景图：只有带 image 的点位才参与预加载与三维球体贴图。 */
export function hasPanoramaImage(point: PanoramaConfig): point is PanoramaConfig & { image: string } {
  return typeof point.image === 'string' && point.image.length > 0;
}

/** 外部嵌入全景：用 iframe 呈现第三方作品。 */
export function isEmbeddedPanorama(point: PanoramaConfig): point is PanoramaConfig & { embedUrl: string } {
  return typeof point.embedUrl === 'string' && point.embedUrl.length > 0;
}

/**
 * 场地模型热点：场地模型里的一台设备。
 * 锚点二选一——`nodeNames`（绑定到场地模型里对应节点，取包围盒中心，推荐）
 * 或 `position`（模型坐标系里的绝对位置）。
 */
export const siteHotspotSchema = z.object({
  id: z.string().min(1),
  /** 目标设备（devices[].id）；点击热点进入该设备的三维模型。 */
  deviceId: z.string().min(1),
  label: z.string().min(1),
  description: z.string().default(''),
  nodeNames: z.array(z.string().min(1)).default([]),
  position: vec3Schema.optional(),
  /** 锚点微调（模型单位），用于把标记挪到设备顶部/正面。 */
  offset: vec3Schema.default([0, 0, 0]),
}).refine(value => value.nodeNames.length > 0 || value.position !== undefined, {
  message: '场地热点必须提供 nodeNames 或 position',
  path: ['nodeNames'],
});

/** 设备模型入口先展示的场地（库外试验场）模型。 */
export const siteModelSchema = z.object({
  id: z.string().min(1),
  name: z.string().min(1),
  summary: z.string().default(''),
  poster: assetUrlSchema,
  source: fileModelSourceSchema,
  camera: cameraSchema,
  hotspots: z.array(siteHotspotSchema).default([]),
});

export const mapTargetSchema = z.discriminatedUnion('kind', [
  z.object({ kind: z.literal('map'), id: z.string().min(1) }),
  z.object({ kind: z.literal('panorama'), id: z.string().min(1) }),
  z.object({ kind: z.literal('device'), id: z.string().min(1) }),
]);

export const mapPointSchema = z.object({
  id: z.string().min(1),
  label: z.string().min(1),
  description: z.string().default(''),
  /** 底图上的归一化位置（0~1）。与 lng/lat 二选一。 */
  x: z.number().min(0).max(1).optional(),
  y: z.number().min(0).max(1).optional(),
  /** 直接写经纬度，由配置层按底图 bounds 换算成 x/y —— 用真实地图时比手算归一化坐标省事。 */
  lng: z.number().min(-180).max(180).optional(),
  lat: z.number().min(-85).max(85).optional(),
  target: mapTargetSchema,
}).refine(value => (value.x !== undefined && value.y !== undefined) || (value.lng !== undefined && value.lat !== undefined), {
  message: '点位必须提供 x/y 或 lng/lat',
  path: ['x'],
}).refine(value => !(value.x !== undefined && value.lng !== undefined), {
  message: '点位的 x/y 与 lng/lat 只能选一种',
  path: ['lng'],
});

const geoBoundsSchema = z.object({
  west: z.number().min(-180).max(180),
  south: z.number().min(-85).max(85),
  east: z.number().min(-180).max(180),
  north: z.number().min(-85).max(85),
}).refine(value => value.west < value.east && value.south < value.north, { message: '地图范围必须满足 west<east 且 south<north' });

const TILE_PLACEHOLDERS = ['{z}', '{x}', '{y}'];

/** 瓦片地址模板必须含 {z}/{x}/{y}。 */
const tileTemplateSchema = z.string().min(1)
  .refine(value => !value.startsWith('http://'), '瓦片地址必须使用 HTTPS 或站内相对路径')
  .refine(value => TILE_PLACEHOLDERS.every(token => value.includes(token)), '瓦片地址必须包含 {z}/{x}/{y} 占位符');

/**
 * 底图有两种来源：
 * - `image`：自托管静态图（离线可用，室内网/展厅首选）；
 * - `tiles`：XYZ/WMTS 瓦片，模板与署名由配置提供。
 */
export const basemapSchema = z.discriminatedUnion('kind', [
  z.object({
    kind: z.literal('image'),
    image: assetUrlSchema,
  }),
  z.object({
    kind: z.literal('tiles'),
    urlTemplate: tileTemplateSchema,
    /**
     * 可选的标注/注记层（如天地图的 cva_w），叠在底图之上，用同一个 bounds 与层级。
     */
    overlayTemplate: tileTemplateSchema.optional(),
    /**
     * 子域名轮询：把一屏几十上百张瓦片摊到多个域名上。
     * 两种写法都支持（见 `tilesForViewport`）：
     * - 模板里写 `{s}`（天地图 `t0`~`t7` 的标准写法）；
     * - 或者模板写死 `t0`，只在这里给出候选数字 —— 这样**旧版前端**（不认识 `{s}`）拿到新配置也不会
     *   把 `t{s}` 这种字面量拼进 URL、导致整屏瓦片全挂。
     * 留空则模板按原样使用（自建金字塔不需要）。
     */
    subdomains: z.array(z.string().min(1)).optional(),
    /**
     * 备用瓦片源：主源每张瓦片重试用尽后，用**同一 z/x/y** 再试这个模板。
     * 用途是"某个网络到主源不通时地图不至于全黑"。必须是同投影同网格（Web Mercator / WGS84）的源，
     * 否则点位会整体偏移（GCJ-02 的高德、腾讯就会偏）。
     */
    fallbackTemplate: tileTemplateSchema.optional(),
    fallbackOverlayTemplate: tileTemplateSchema.optional(),
    attribution: z.string().min(1),
    minZoom: z.number().int().min(0).max(22),
    maxZoom: z.number().int().min(1).max(22),
    bounds: geoBoundsSchema,
  }).refine(value => value.minZoom <= value.maxZoom, { message: '瓦片最小层级不能大于最大层级', path: ['minZoom'] }),
]);

export const mapSchema = z.object({
  id: z.string().min(1),
  name: z.string().min(1),
  /** 层级名，用于面包屑与提示，例如“院区及周边”。 */
  level: z.string().min(1).default(''),
  basemap: basemapSchema,
  /**
   * 进入这一级时的初始视野：以某点为中心。
   * 三种定尺度方式，优先级 `spanMeters` > `zoom` > `scale`：
   * - `spanMeters`：**屏幕横向覆盖多少米**（推荐）。设备无关——手机和平板开场看到同样宽的地面，
   *   院区的视觉大小一致；只写 `zoom` 时屏幕越宽看到的地面越多，同一院区在桌面端会小 2.5 倍。
   * - `zoom`：瓦片层级，直观但受屏幕宽度影响（见上）。
   * - `scale`：相对"整幅铺满"的倍数（1 = 铺满）。
   */
  initialView: z.object({
    lng: z.number().min(-180).max(180),
    lat: z.number().min(-85).max(85),
    spanMeters: z.number().min(50).max(500_000).optional(),
    zoom: z.number().min(0).max(22).optional(),
    scale: z.number().min(1).max(64).default(1),
  }).optional(),
  /** 上级地图 id；根地图缺省。面包屑靠它上溯，也用于校验下钻归属。 */
  parentId: z.string().min(1).optional(),
  description: z.string().default(''),
  points: z.array(mapPointSchema).default([]),
}).refine(value => !value.initialView || value.basemap.kind === 'tiles', {
  message: 'initialView 需要底图提供 bounds，仅瓦片底图支持',
  path: ['initialView'],
});

export const museumConfigSchema = z.object({
  version: z.literal(1),
  site: z.object({
    name: z.string().min(1),
    defaultRoute: z.string().startsWith('/'),
  }),
  maps: z.array(mapSchema).min(1),
  devices: z.array(deviceSchema),
  panoramas: z.array(panoramaSchema),
  /** 可选：设备模型的入口场地模型（点进来先看场地，点场地里的设备再看设备）。 */
  siteModel: siteModelSchema.optional(),
  resources: z.array(resourceSchema),
  /** 资料事件类型的受控词表（resources[].eventType 的取值集合）。 */
  eventTypes: z.array(eventTypeSchema).default([]),
  /** 策展专辑（resources[].collectionIds 的取值集合）。 */
  collections: z.array(collectionSchema).default([]),
});

export type DeviceConfig = z.infer<typeof deviceSchema>;
export type DevicePartConfig = z.infer<typeof devicePartSchema>;
export type PanoramaConfig = z.infer<typeof panoramaSchema>;
export type SiteModelConfig = z.infer<typeof siteModelSchema>;
export type SiteHotspotConfig = z.infer<typeof siteHotspotSchema>;
export type CameraConfig = z.infer<typeof cameraSchema>;
export type FileModelSource = z.infer<typeof fileModelSourceSchema>;
export type ResourceConfig = z.infer<typeof resourceSchema>;
export type ResourceAboutConfig = z.infer<typeof resourceAboutSchema>;
export type EventTypeConfig = z.infer<typeof eventTypeSchema>;
export type CollectionConfig = z.infer<typeof collectionSchema>;
/**
 * 解析后的配置类型：点位在配置层就把 lng/lat 换算成了 x/y，因此对外始终有 x/y。
 * （输入类型里 x/y 与 lng/lat 都是可选的，二选一即可。）
 */
export type MapPointConfig = Omit<z.infer<typeof mapPointSchema>, 'x' | 'y' | 'lng' | 'lat'> & { x: number; y: number };
export type MapConfig = Omit<z.infer<typeof mapSchema>, 'points'> & { points: MapPointConfig[] };
export type MapTargetConfig = z.infer<typeof mapTargetSchema>;
export type BasemapConfig = z.infer<typeof basemapSchema>;
export type MuseumConfig = Omit<z.infer<typeof museumConfigSchema>, 'maps'> & { maps: MapConfig[] };

export interface ConfigIssue {
  path: string;
  message: string;
}

function hasMissingReference(ids: string[], validIds: Set<string>) {
  return ids.some(id => !validIds.has(id));
}

/**
 * 资料的主归属层级：**关系可以跨级，层级只有一个**。
 * 一条资料可以同时"与某台设备有关"（会出现在设备页）与"属于项目/机构级"（不会被当成设备自身的资料）——
 * 判定顺序 program → site → device，用于档案页的归属筛选与卡片上的层级徽标。
 */
export function resourceScope(resource: ResourceConfig): 'program' | 'site' | 'device' | null {
  if (resource.about.some(item => item.kind === 'program')) return 'program';
  if (resource.about.some(item => item.kind === 'site')) return 'site';
  if (resource.about.some(item => item.kind === 'device')) return 'device';
  return null;
}

/** 两个 id 列表是否等价（顺序无关、不看重复）。 */
function sameIds(left: string[], right: string[]) {
  const normalize = (ids: string[]) => [...new Set(ids)].sort().join('\u0000');
  return normalize(left) === normalize(right);
}

function assertUniqueIds(label: string, items: Array<{ id: string }>) {
  const seen = new Set<string>();
  for (const item of items) {
    if (seen.has(item.id)) throw new Error(`${label} 存在重复 ID：${item.id}`);
    seen.add(item.id);
  }
}

/** 地图层级若出现环，面包屑会无限上溯；发现环就把该地图降为根并记录问题。 */
function detachMapCycles(maps: MapConfig[], issues: ConfigIssue[]): MapConfig[] {
  const byId = new Map(maps.map(map => [map.id, map]));
  return maps.map(map => {
    const visited = new Set([map.id]);
    let cursor = map.parentId ? byId.get(map.parentId) : undefined;
    while (cursor) {
      if (visited.has(cursor.id)) {
        issues.push({ path: `maps.${map.id}.parentId`, message: '地图层级存在环，已按根地图处理' });
        return { ...map, parentId: undefined };
      }
      visited.add(cursor.id);
      cursor = cursor.parentId ? byId.get(cursor.parentId) : undefined;
    }
    return map;
  });
}

export function parseMuseumConfig(input: unknown): { config: MuseumConfig; issues: ConfigIssue[] } {
  if (input && typeof input === 'object' && 'version' in input && input.version !== 1) {
    throw new Error(`不支持的配置版本：${String(input.version)}`);
  }

  const parsed = museumConfigSchema.safeParse(input);
  if (!parsed.success) {
    const detail = parsed.error.issues.map(issue => `${issue.path.join('.')}: ${issue.message}`).join('；');
    throw new Error(`配置格式错误：${detail}`);
  }

  assertUniqueIds('resources', parsed.data.resources);
  assertUniqueIds('devices', parsed.data.devices);
  assertUniqueIds('panoramas', parsed.data.panoramas);
  assertUniqueIds('maps', parsed.data.maps);
  assertUniqueIds('eventTypes', parsed.data.eventTypes);
  assertUniqueIds('collections', parsed.data.collections);
  if (parsed.data.siteModel) assertUniqueIds('siteModel.hotspots', parsed.data.siteModel.hotspots);

  const issues: ConfigIssue[] = [];
  const resourceIds = new Set(parsed.data.resources.map(item => item.id));
  const panoramaIds = new Set(parsed.data.panoramas.map(item => item.id));

  // 受控词表（事件类型 / 专辑）在配置里，这里只校验引用合法性。
  const eventTypeIds = new Set(parsed.data.eventTypes.map(item => item.id));
  const collectionIdSet = new Set(parsed.data.collections.map(item => item.id));

  // 资料 → 设备 的派生关系：**单一来源是 resources[].about**，
  // 设备侧的 resourceIds 由它生成，手写值只用来报冲突（避免两处漂移）。
  const declaredDeviceIds = new Set(parsed.data.devices.map(item => item.id));
  const siteModelId = parsed.data.siteModel?.id;
  const derivedResourceIds = new Map<string, string[]>();
  for (const resource of parsed.data.resources) {
    if (resource.eventType && !eventTypeIds.has(resource.eventType)) {
      issues.push({ path: `resources.${resource.id}.eventType`, message: `事件类型 ${resource.eventType} 不在 eventTypes 词表里` });
    }
    for (const collectionId of resource.collectionIds) {
      if (!collectionIdSet.has(collectionId)) {
        issues.push({ path: `resources.${resource.id}.collectionIds`, message: `专辑 ${collectionId} 不在 collections 里` });
      }
    }
    for (const about of resource.about) {
      if (about.kind === 'program') continue;
      const label = about.kind === 'device' ? '设备' : '场地';
      const known = about.kind === 'device' ? declaredDeviceIds.has(about.id) : siteModelId === about.id;
      if (!known) {
        issues.push({ path: `resources.${resource.id}.about`, message: `资料关联了不存在的${label} ${about.id}` });
        continue;
      }
      if (about.kind === 'device') {
        const list = derivedResourceIds.get(about.id);
        if (list) list.push(resource.id);
        else derivedResourceIds.set(about.id, [resource.id]);
      }
    }
  }

  const devices = parsed.data.devices.filter(device => {
    const ids = [...device.resourceIds, ...device.parts.flatMap(part => part.resourceIds)];
    if (!hasMissingReference(ids, resourceIds)) return true;
    issues.push({ path: `devices.${device.id}.resourceIds`, message: '设备引用了不存在的资源' });
    return false;
  }).map(device => {
    const derived = derivedResourceIds.get(device.id) ?? [];
    if (device.resourceIds.length > 0 && !sameIds(device.resourceIds, derived)) {
      issues.push({ path: `devices.${device.id}.resourceIds`, message: '手写的资料 id 与资料 about 的派生结果不一致，已按 about 派生' });
    }
    return { ...device, resourceIds: derived };
  });
  const panoramas = parsed.data.panoramas.filter(panorama => {
    if (panorama.hotspots.every(hotspot => panoramaIds.has(hotspot.targetId))) return true;
    issues.push({ path: `panoramas.${panorama.id}.hotspots`, message: '全景热点指向不存在的点位' });
    return false;
  });
  // 地图点位可下钻到子地图、进入全景，或打开设备；下钻必须在子地图里声明上级，
  // 否则面包屑与返回上级都会指向错误的位置。
  const mapIds = new Set(parsed.data.maps.map(item => item.id));
  const deviceIds = new Set(devices.map(item => item.id));
  // 场地热点必须指向一台真实存在的设备，否则点了没地方去，直接丢弃并记录问题。
  const siteModel = parsed.data.siteModel && {
    ...parsed.data.siteModel,
    hotspots: parsed.data.siteModel.hotspots.filter(hotspot => {
      if (deviceIds.has(hotspot.deviceId)) return true;
      issues.push({ path: `siteModel.hotspots.${hotspot.id}`, message: '场地热点指向不存在的设备' });
      return false;
    }),
  };
  const maps = parsed.data.maps.map(map => {
    let parentId = map.parentId;
    if (parentId && !mapIds.has(parentId)) {
      issues.push({ path: `maps.${map.id}.parentId`, message: '上级地图不存在' });
      parentId = undefined;
    }
    const points = map.points.flatMap(point => {
      const { kind, id } = point.target;
      const known = kind === 'map' ? mapIds.has(id)
        : kind === 'panorama' ? panoramaIds.has(id)
          : deviceIds.has(id);
      if (!known) {
        issues.push({ path: `maps.${map.id}.points.${point.id}`, message: `地图标记指向不存在的${kind}` });
        return [];
      }
      if (kind === 'map' && parsed.data.maps.find(item => item.id === id)?.parentId !== map.id) {
        issues.push({ path: `maps.${map.id}.points.${point.id}`, message: '下钻目标没有把当前地图声明为上级' });
        return [];
      }
      // 用经纬度写点位时按底图 bounds 换算；没有 bounds 的静态底图无法换算。
      if (point.lng !== undefined && point.lat !== undefined) {
        const bounds = map.basemap.kind === 'tiles' ? map.basemap.bounds : undefined;
        if (!bounds) {
          issues.push({ path: `maps.${map.id}.points.${point.id}`, message: '该底图没有 bounds，点位不能用 lng/lat，请改用 x/y' });
          return [];
        }
        const { x, y } = normalizeLngLat(point.lng, point.lat, bounds);
        return [{ ...point, x, y }];
      }
      return [{ ...point, x: point.x ?? 0.5, y: point.y ?? 0.5 }];
    });
    return { ...map, parentId, points };
  });
  const rootedMaps = detachMapCycles(maps, issues);
  if (!rootedMaps.some(map => !map.parentId)) {
    issues.push({ path: 'maps', message: '没有根地图，已按配置顺序取第一张' });
  }

  return { config: { ...parsed.data, devices, panoramas, siteModel, maps: rootedMaps }, issues };
}
