/**
 * 页面内「地图设置」的本地覆盖层。
 *
 * 站点是纯静态部署、没有后端，所以页面上选定的**默认视图**与**武高所位置**先落进
 * localStorage（立即生效、刷新仍在），同时可以导出成一段 JSON 写回 `config/museum.json`
 * 固化到所有设备。优先级：本地覆盖 > museum.json。
 *
 * 之所以要覆盖层而不是直接改配置：浏览器改不了磁盘上的文件；而「先看效果、满意再固化」
 * 才是配地图时的正常节奏。
 */

import { normalizeLngLat, type GeoBounds } from '../shared/geo';
import type { MapConfig, MuseumConfig } from './schema';

export const OVERRIDES_STORAGE_KEY = 'museum.map-overrides.v1';

export interface MapOverrides {
  initialView?: { lng: number; lat: number; spanMeters?: number; zoom?: number; scale?: number };
  /** 点位位置覆盖，按点位 id 记；用于「选定武高所位置」。 */
  markers?: Record<string, { lng: number; lat: number }>;
}

export interface Overrides {
  version: 1;
  defaultRoute?: string;
  maps?: Record<string, MapOverrides>;
}

export const EMPTY_OVERRIDES: Overrides = { version: 1 };

function isFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}

function readView(input: unknown): MapOverrides['initialView'] | undefined {
  if (!input || typeof input !== 'object') return undefined;
  const value = input as Record<string, unknown>;
  if (!isFiniteNumber(value.lng) || !isFiniteNumber(value.lat)) return undefined;
  const view: MapOverrides['initialView'] = { lng: value.lng, lat: value.lat };
  if (isFiniteNumber(value.spanMeters)) view.spanMeters = value.spanMeters;
  if (isFiniteNumber(value.zoom)) view.zoom = value.zoom;
  if (isFiniteNumber(value.scale)) view.scale = value.scale;
  return view;
}

function readMarkers(input: unknown): Record<string, { lng: number; lat: number }> | undefined {
  if (!input || typeof input !== 'object') return undefined;
  const out: Record<string, { lng: number; lat: number }> = {};
  for (const [id, raw] of Object.entries(input as Record<string, unknown>)) {
    if (!raw || typeof raw !== 'object') continue;
    const value = raw as Record<string, unknown>;
    if (isFiniteNumber(value.lng) && isFiniteNumber(value.lat)) out[id] = { lng: value.lng, lat: value.lat };
  }
  return Object.keys(out).length ? out : undefined;
}

/** 容忍脏数据：localStorage 里可能是旧版本或被手工改坏的内容，读不动就当没有。 */
export function parseOverrides(input: unknown): Overrides {
  if (!input || typeof input !== 'object') return { ...EMPTY_OVERRIDES };
  const value = input as Record<string, unknown>;
  const overrides: Overrides = { version: 1 };
  if (typeof value.defaultRoute === 'string' && value.defaultRoute.startsWith('/')) {
    overrides.defaultRoute = value.defaultRoute;
  }
  if (value.maps && typeof value.maps === 'object') {
    const maps: Record<string, MapOverrides> = {};
    for (const [mapId, raw] of Object.entries(value.maps as Record<string, unknown>)) {
      if (!raw || typeof raw !== 'object') continue;
      const entry = raw as Record<string, unknown>;
      const view = readView(entry.initialView);
      const markers = readMarkers(entry.markers);
      if (view || markers) maps[mapId] = { ...(view ? { initialView: view } : {}), ...(markers ? { markers } : {}) };
    }
    if (Object.keys(maps).length) overrides.maps = maps;
  }
  return overrides;
}

export function loadOverrides(storage: Pick<Storage, 'getItem'> | undefined = globalThis.localStorage): Overrides {
  try {
    const raw = storage?.getItem(OVERRIDES_STORAGE_KEY);
    return raw ? parseOverrides(JSON.parse(raw)) : { ...EMPTY_OVERRIDES };
  } catch {
    return { ...EMPTY_OVERRIDES };
  }
}

export function saveOverrides(
  overrides: Overrides,
  storage: Pick<Storage, 'setItem'> | undefined = globalThis.localStorage,
) {
  try {
    storage?.setItem(OVERRIDES_STORAGE_KEY, JSON.stringify(overrides));
  } catch { /* 隐私模式下写不进去时静默失败，页面仍可用 */ }
}

export function clearOverrides(storage: Pick<Storage, 'removeItem'> | undefined = globalThis.localStorage) {
  try {
    storage?.removeItem(OVERRIDES_STORAGE_KEY);
  } catch { /* 同上 */ }
}

export function hasOverrides(overrides: Overrides): boolean {
  return Boolean(overrides.defaultRoute) || Boolean(overrides.maps && Object.keys(overrides.maps).length);
}

function pointGeometry(lng: number, lat: number, bounds: GeoBounds | undefined) {
  if (!bounds) return null;
  const { x, y } = normalizeLngLat(lng, lat, bounds);
  if (x < 0 || x > 1 || y < 0 || y > 1) return null; // 落在底图范围外，忽略这条覆盖
  return { x, y };
}

/** 把覆盖层套用到已解析的配置上，返回新对象（不改原配置）。 */
export function applyOverrides(config: MuseumConfig, overrides: Overrides): MuseumConfig {
  if (!hasOverrides(overrides)) return config;
  const maps: MapConfig[] = config.maps.map(map => {
    const entry = overrides.maps?.[map.id];
    if (!entry) return map;
    const bounds = map.basemap.kind === 'tiles' ? map.basemap.bounds : undefined;
    const points = map.points.map(point => {
      const marker = entry.markers?.[point.id];
      if (!marker) return point;
      const geometry = pointGeometry(marker.lng, marker.lat, bounds);
      return geometry ? { ...point, ...geometry } : point;
    });
    const { markers: _markers, ...rest } = entry;
    void _markers;
    if (rest.initialView && map.basemap.kind === 'tiles') {
      const view = rest.initialView;
      const inside = pointGeometry(view.lng, view.lat, bounds);
      if (inside) {
        return {
          ...map,
          points,
          initialView: {
            lng: view.lng,
            lat: view.lat,
            ...(view.spanMeters === undefined ? {} : { spanMeters: view.spanMeters }),
            ...(view.zoom === undefined ? {} : { zoom: view.zoom }),
            scale: view.scale ?? 1,
          },
        };
      }
    }
    return { ...map, points };
  });
  return {
    ...config,
    site: overrides.defaultRoute ? { ...config.site, defaultRoute: overrides.defaultRoute } : config.site,
    maps,
  };
}
