import type { MapConfig, MuseumConfig } from './schema';

export function createRepository(config: MuseumConfig) {
  const resources = new Map(config.resources.map(item => [item.id, item]));
  const maps = new Map(config.maps.map(item => [item.id, item]));
  const children = new Map<string, MapConfig[]>();
  for (const map of config.maps) {
    const key = map.parentId ?? '';
    const list = children.get(key);
    if (list) list.push(map);
    else children.set(key, [map]);
  }
  const rootMap = config.maps.find(item => !item.parentId) ?? config.maps[0];

  const getMapPath = (id: string): MapConfig[] => {
    const path: MapConfig[] = [];
    const visited = new Set<string>();
    let cursor = maps.get(id);
    while (cursor && !visited.has(cursor.id)) {
      visited.add(cursor.id);
      path.unshift(cursor);
      cursor = cursor.parentId ? maps.get(cursor.parentId) : undefined;
    }
    return path;
  };

  return {
    getDevice: (id: string) => config.devices.find(item => item.id === id),
    getPanorama: (id: string) => config.panoramas.find(item => item.id === id),
    /** 设备模型的入口场地模型（配置可选；缺省时设备页直接展示设备）。 */
    getSiteModel: () => config.siteModel,
    getResource: (id: string) => resources.get(id),
    getResources: (ids: string[]) => ids.flatMap(id => resources.get(id) ?? []),
    getMap: (id: string) => maps.get(id),
    getRootMap: () => rootMap,
    getMapChildren: (id: string) => children.get(id) ?? [],
    /** 从根到该地图的层级路径，用于面包屑。 */
    getMapPath,
    /** 反向查找：某个全景出现在哪张地图上（全景页“在地图查看位置”用）。 */
    findMapIdForPanorama: (panoramaId: string) =>
      config.maps.find(map => map.points.some(point => point.target.kind === 'panorama' && point.target.id === panoramaId))?.id,
  };
}

export type MuseumRepository = ReturnType<typeof createRepository>;
