import { useEffect, useState } from 'react';

export interface FpsStats {
  /** Average frames per second over the last second. */
  fps: number;
  /** Duration of the most recent frame in milliseconds. */
  frameTime: number;
  /** Milliseconds from the last tap/touch to the following frame (0 = none pending). */
  inputLatency: number;
}

/**
 * Lightweight on-device performance probe. Measures real frame cadence via
 * requestAnimationFrame plus a rough input-to-frame latency for tap/touch.
 */
export function useFpsCounter(): FpsStats {
  const [stats, setStats] = useState<FpsStats>({ fps: 0, frameTime: 0, inputLatency: 0 });

  useEffect(() => {
    let rafId = 0;
    let frames = 0;
    let windowStart = performance.now();
    let lastFrame = windowStart;
    let inputTime = 0;
    let inputPending = false;

    const markInput = () => {
      inputTime = performance.now();
      inputPending = true;
    };
    window.addEventListener('pointerdown', markInput);
    window.addEventListener('touchstart', markInput);

    const loop = (time: number) => {
      rafId = requestAnimationFrame(loop);
      frames += 1;
      const frameTime = time - lastFrame;
      lastFrame = time;

      if (inputPending) {
        inputPending = false;
        setStats(previous => ({ ...previous, inputLatency: Math.max(0, Math.round(time - inputTime)) }));
      }

      if (time - windowStart >= 1000) {
        setStats(previous => ({
          ...previous,
          fps: Math.round((frames * 1000) / (time - windowStart)),
          frameTime: Math.round(frameTime),
        }));
        frames = 0;
        windowStart = time;
      }
    };

    rafId = requestAnimationFrame(loop);
    return () => {
      cancelAnimationFrame(rafId);
      window.removeEventListener('pointerdown', markInput);
      window.removeEventListener('touchstart', markInput);
    };
  }, []);

  return stats;
}
