import { lazy, Suspense, useRef, useState } from 'react';
import { HashRouter, Navigate, Route, Routes, useLocation } from 'react-router-dom';
import { useMuseumConfig } from '../config/ConfigProvider';
import { AppShell } from '../shared/AppShell';
import { PerformanceOverlay } from '../shared/PerformanceOverlay';
import { RouteErrorBoundary } from '../shared/RouteErrorBoundary';

const SHOW_PERF = new URLSearchParams(window.location.search).get('perf') === '1';

const ArchivePage = lazy(() => import('../features/archive/ArchivePage').then(module => ({ default: module.ArchivePage })));
const DevicePage = lazy(() => import('../features/devices/DevicePage').then(module => ({ default: module.DevicePage })));
const SitePage = lazy(() => import('../features/site/SitePage').then(module => ({ default: module.SitePage })));
const PanoramaPage = lazy(() => import('../features/panorama/PanoramaPage').then(module => ({ default: module.PanoramaPage })));
const MapPage = lazy(() => import('../features/map/MapPage').then(module => ({ default: module.MapPage })));

function RoutePanel({ title, detail }: { title: string; detail: string }) {
  return (
    <section className="route-panel">
      <span>武高所数字博物馆</span>
      <h1>{title}</h1>
      <p>{detail}</p>
    </section>
  );
}

/**
 * 常驻槽位：分组页面在离开路由后**不卸载**，只把外层盒子隐藏。
 *
 * 为什么需要它：场地模型 19.4 MB / 设备模型 5.5 MB，重新挂载 = 重新下载 + 重新解析 +
 * 重新上传 GPU；地图则要重新建瓦片图层并把视野重置回默认。切一次底部导航就付一次这个代价，
 * 而且相机角度、拆解进度、选中部件、地图缩放位置全丢。
 *
 * 做法是经典的 keep-alive：本分组激活时沿用实时 location，失活时冻结在**最后一次**
 * 属于本分组的 location 上，这样 `<Routes>` 匹配结果不变，React 保留同一棵子树。
 * 返回时槽位重新显示，画面/状态都是原样，不需要任何恢复逻辑。
 */
function useKeepAliveSlot(active: boolean) {
  const location = useLocation();
  const frozen = useRef(location);
  const [mounted, setMounted] = useState(active);
  // 先在渲染期把这个"最后位置"记下来：失活的那一次渲染必须已经拿到旧值，
  // 否则冻结的会是新页面的 location，槽位就会错误地重新匹配。
  if (active) frozen.current = location;
  // 首次进入时同步挂载（渲染期 setState，React 会在提交前立刻重渲染），
  // 避免"路由已经切过来、槽位还没挂"的一帧空白。
  if (active && !mounted) setMounted(true);
  return { slotLocation: active ? location : frozen.current, mounted };
}

/** 兜底跳转：路由已经被某个常驻槽位接管时返回 null，否则重定向到默认页。 */
function FallbackRedirect({ to, handled }: { to: string; handled: boolean }) {
  return handled ? null : <Navigate to={to} replace />;
}

function RoutedContent() {
  const location = useLocation();
  // 默认页由配置决定（site.defaultRoute），页面内「地图设置」也能改它（写入本地覆盖层）。
  const { config } = useMuseumConfig();
  const fallback = config.site.defaultRoute || '/map';
  const pathname = location.pathname === '/' ? '/' : location.pathname.replace(/\/+$/, '');
  const siteActive = pathname === '/devices';
  const deviceActive = pathname.startsWith('/devices/');
  // 「全景漫游」这一组 = 地图（含盖在地图上的漫游层）+ 保留的独立全景深链。
  const mapActive = pathname === '/map' || pathname.startsWith('/map/') || pathname === '/panorama' || pathname.startsWith('/panorama/');
  const site = useKeepAliveSlot(siteActive);
  const device = useKeepAliveSlot(deviceActive);
  const map = useKeepAliveSlot(mapActive);
  // 设备槽的 error boundary key 取自**冻结后**的路径：用实时路径会让离开页面时 key 变化，
  // 那就等于重新挂载，keep-alive 白做。
  const devicePath = device.slotLocation.pathname;
  const deviceId = devicePath.startsWith('/devices/') ? devicePath.split('/')[2] ?? '' : '';
  // 地图槽里放着两个页面（地图 / 独立全景），error boundary 同理按**冻结后**的类型分组。
  const mapKind = map.slotLocation.pathname.startsWith('/panorama') ? 'panorama' : 'map';
  return (
    <AppShell>
      {/* 常驻：全景漫游（地图 + 盖在地图上的漫游层 + 独立全景深链） */}
      {map.mounted && (
        <div className="route-slot" hidden={!mapActive}>
          <RouteErrorBoundary key={`map:${mapKind}`}>
            <Suspense fallback={<RoutePanel title="全景漫游" detail="正在加载地图" />}>
              <Routes location={map.slotLocation}>
                <Route path="/map/:mapId?" element={<MapPage active={mapActive} />} />
                {/* 漫游是地图页的一层（盖在地图上），因此仍然属于「全景漫游」这一项。 */}
                <Route path="/map/:mapId/roam/:pointId" element={<MapPage active={mapActive} />} />
                {/* 保留独立的全景路由：二维码/外部链接仍可直接深链到漫游。 */}
                <Route path="/panorama/:pointId?" element={<PanoramaPage active={mapActive} />} />
              </Routes>
            </Suspense>
          </RouteErrorBoundary>
        </div>
      )}
      {/* 常驻：场地（/devices） */}
      {site.mounted && (
        <div className="route-slot" hidden={!siteActive}>
          <RouteErrorBoundary key="site">
            <Suspense fallback={<RoutePanel title="设备模型" detail="正在加载场地模型" />}>
              <Routes location={site.slotLocation}>
                <Route path="/devices" element={<SitePage />} />
              </Routes>
            </Suspense>
          </RouteErrorBoundary>
        </div>
      )}
      {/* 常驻：设备三维详情（/devices/:id 与 /devices/:id/disassembly 同一槽位） */}
      {device.mounted && (
        <div className="route-slot" hidden={!deviceActive}>
          <RouteErrorBoundary key={`device:${deviceId}`}>
            <Suspense fallback={<RoutePanel title="设备模型" detail="正在加载三维设备" />}>
              <Routes location={device.slotLocation}>
                <Route path="/devices/:deviceId" element={<DevicePage active={deviceActive} />} />
                <Route path="/devices/:deviceId/disassembly" element={<DevicePage disassemblyEntry active={deviceActive} />} />
              </Routes>
            </Suspense>
          </RouteErrorBoundary>
        </div>
      )}
      <RouteErrorBoundary key={location.pathname}>
        <Routes>
          <Route path="/archive/:resourceId?" element={<Suspense fallback={<RoutePanel title="数字档案" detail="正在加载档案" />}><ArchivePage /></Suspense>} />
          <Route path="*" element={<FallbackRedirect to={fallback} handled={siteActive || deviceActive || mapActive} />} />
        </Routes>
      </RouteErrorBoundary>
    </AppShell>
  );
}

export function App() {
  return (
    <HashRouter>
      <RoutedContent />
      {SHOW_PERF && <PerformanceOverlay />}
    </HashRouter>
  );
}
