import { createContext, type PropsWithChildren, useContext, useEffect, useMemo, useState } from 'react';
import { loadMuseumConfig } from './loadConfig';
import { createRepository, type MuseumRepository } from './repository';
import type { ConfigIssue, MuseumConfig } from './schema';

interface ConfigValue {
  config: MuseumConfig;
  issues: ConfigIssue[];
  repository: MuseumRepository;
}

interface ParsedConfig {
  config: MuseumConfig;
  issues: ConfigIssue[];
}

interface ConfigProviderProps extends PropsWithChildren {
  load?: () => Promise<ParsedConfig>;
}

const ConfigContext = createContext<ConfigValue | null>(null);
const defaultConfigLoader = () => loadMuseumConfig();

export function ConfigProvider({ children, load = defaultConfigLoader }: ConfigProviderProps) {
  const [attempt, setAttempt] = useState(0);
  const [result, setResult] = useState<ParsedConfig | null>(null);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    let active = true;
    setResult(null);
    setError(null);
    void load().then(value => {
      if (active) setResult(value);
    }).catch(reason => {
      if (active) setError(reason instanceof Error ? reason : new Error(String(reason)));
    });
    return () => { active = false; };
  }, [attempt, load]);

  const value = useMemo<ConfigValue | null>(() => result ? {
    ...result,
    repository: createRepository(result.config),
  } : null, [result]);

  if (error) {
    return (
      <section className="status-panel" role="alert">
        <h1>展馆配置无法加载</h1>
        <p>{error.message}</p>
        <button type="button" onClick={() => setAttempt(value => value + 1)}>重新加载</button>
      </section>
    );
  }
  if (!value) return <section className="status-panel" aria-live="polite">正在加载展馆配置</section>;
  return <ConfigContext.Provider value={value}>{children}</ConfigContext.Provider>;
}

export function useMuseumConfig() {
  const value = useContext(ConfigContext);
  if (!value) throw new Error('useMuseumConfig 必须在 ConfigProvider 内使用');
  return value;
}
