import type { CSSProperties, PropsWithChildren } from 'react';
import { NavLink } from 'react-router-dom';
import { routeItems } from '../app/routes';
import { prefetchRouteModule } from './prefetch';

export function AppShell({ children }: PropsWithChildren) {
  return (
    <div className="app-viewport">
      <div className="mobile-shell">
        <main>{children}</main>
        <nav
          className="bottom-nav"
          aria-label="主要页面"
          // 列数/行数由条目数决定（手机是横排几等分、宽屏是左侧导航几行），
          // 这样增删栏目只改 routes.tsx，不用回来改 CSS。
          style={{ '--nav-count': routeItems.length } as CSSProperties}
        >
          {routeItems.map(({ to, label, icon: Icon }) => (
            <NavLink
              key={to}
              to={to}
              className={({ isActive }) => isActive ? 'is-active' : undefined}
              onPointerEnter={() => prefetchRouteModule(to)}
              onFocus={() => prefetchRouteModule(to)}
            >
              <Icon aria-hidden="true" size={21} />
              <span>{label}</span>
            </NavLink>
          ))}
        </nav>
      </div>
    </div>
  );
}
